var Runner = require('./plan_runner');

exports.start = function (options) {
  var waits = exports.waits(options);
  return new Runner(waits, {
    endless: options && options.endless,
  });
};

exports.waits = function (options) {
  if (options instanceof Array) {
    return [].concat(options);
  }
  var opts = { steps: 3, base: 10, growth: 2 };
  for (var key in options) {
    opts[key] = options[key];
  }
  var out = [];
  for (var i = 0; i < opts.steps; i++) {
    out.push(this.waitFor(i, opts));
  }
  out.sort(function (a, b) {
    return a - b;
  });
  return out;
};

exports.waitFor = function (attempt, opts) {
  return Math.round(opts.base * Math.pow(opts.growth, attempt));
};

exports.describe = function (options) {
  var runner = exports.start(options);
  var out = [];
  for (var wait = runner.next(); wait >= 0; wait = runner.next()) {
    out.push(wait);
  }
  return out.join(',') + ' (' + runner.count() + ')';
};
